// Lumière Skin Clinic: this report's contacts, and the newest deals in its pipeline (matched to those contacts next).
const job = $('Start report').first().json;
const G = 'https://services.leadconnectorhq.com', L = 'lX1GDRcqD985tKgOM4I3', P = 'e3YMhd6OJWtcGA9MFPnx';
return [
  { json: { kind: 'contacts', req: { method: 'POST', url: `${G}/contacts/search`, body: { locationId: L, page: 1, pageLimit: 100, filters: [{ field: 'tags', operator: 'eq', value: job.select.tag }] } } } },
  // newest first; a deal is never older than its contact, so paging stops once it reaches back before the week
  { json: { kind: 'deals', stopBefore: Date.parse(job.weekStart), req: { method: 'GET', url: `${G}/opportunities/search?location_id=${L}&pipeline_id=${P}&limit=100` } } },
];

// requests refused for going over the rate limit; none = one empty item (always output data), so the IF can route it
// pairedItem says which request a reply answers (a paged read gives several replies per request)
const sent = $('Clinic: read').all().map(i => i.json);
const seen = new Set();
return $input.all().flatMap((it, k) => { const i = it.pairedItem?.item ?? k; if (it.json.statusCode !== 429 || seen.has(i)) return []; seen.add(i); return [{ json: { ...sent[i], i } }]; });

