/*@lib*/
const setStep = (steps, key, status, reason) => steps.map(s => s.key === key ? (reason ? { key, status, reason } : { key, status }) : s);
const pages = n => { const r = [], put = (items, at) => items.forEach((it, k) => (r[at(it.pairedItem?.item ?? k)] ??= []).push(it.json)); put($(n).all(), i => i); if ($(`${n} (retry)`).isExecuted) { const idx = $(`${n} (refused)`).all().map(i => i.json.i); idx.forEach(i => { r[i] = []; }); put($(`${n} (retry)`).all(), k => idx[k]); } return r; };
// The report uses what GoHighLevel has, read back from it, like it would for a real client.
const job = $('Start report').first().json;
const crypto = require('crypto');
const sha256 = s => crypto.createHash('sha256').update(s).digest('hex');
const nowSec = Math.floor(Date.now() / 1000);
let steps = job.steps;
const NAMES = {"clinic":["Clinic","Lumière Skin Clinic"],"store":["Store","Northwind Home"]};
const readNotes = [], out = {};
for (const [client, [label, name]] of Object.entries(NAMES)) {
  const got = pages(`GHL ${client}: read`);
  const r = Object.fromEntries($(`${label}: read`).all().map((s, i) => [s.json.kind, got[i] || []]));
  const c = joinPages(r.contacts, 'contacts', 100, 100), d = joinPages(r.deals, 'opportunities', 100, 100);
  const contacts = c?.rows ?? null, deals = d?.rows ?? null;
  if (!contacts || !deals) readNotes.push(`${name}: GoHighLevel couldn't be read`);
  else if (c.more || d.more) readNotes.push(`${name}: more than 10000 records; only the first 10000 were read`);
  const dealOf = new Map((deals || []).map(d => [d.contactId, d]));
  const leads = (contacts || []).map(c => {
    // ponytail: the demo's made-up date is kept in a created: tag; a real contact uses its dateAdded
    const d = dealOf.get(c.id), created = (c.tags || []).find(t => t.startsWith('created:'));
    return { id: c.id, firstName: c.firstName ?? '', lastName: c.lastName ?? '', email: c.email ?? '', phone: c.phone ?? '', source: c.source ?? null,
      createdAt: new Date(created ? +created.slice(8) : Date.parse(c.dateAdded)).toISOString(),
      outcome: !d ? 'open' : d.status === 'won' ? 'converted' : 'cancelled', value: d ? Number(d.monetaryValue) || 0 : 0, flags: [] };
  });
  const meta = buildMetaEvents(client, leads, job.problems, nowSec, sha256);
  out[client] = { client, name, leads, spend: job.spend[client], ...meta };
}
if (readNotes.length) steps = setStep(steps, 'ghl', 'failed', readNotes.join('; '));
steps = setStep(steps, 'spend', 'done');
steps = setStep(steps, 'meta', 'running');
return [{ json: { runId: job.runId, problems: job.problems, weekStart: job.weekStart, clients: out, steps } }];

const { clients } = $('CRM data').first().json;
const body = data => ({ data, test_event_code: 'TEST68789' });
const reqs = [];
for (const c of Object.values(clients)) {
  // ponytail: always one request per client, even with no events (Meta then answers 400; counted as 0 sent)
  reqs.push({ client: c.client, kind: 'main', count: c.events.length, req: { method: 'POST', url: 'https://graph.facebook.com/v23.0/2897515730634456/events', body: body(c.events) } });
  // the deliberately too-old event goes alone, so Meta's rejection can't sink the real batch
  if (c.edgeEvents.length) reqs.push({ client: c.client, kind: 'edge', count: c.edgeEvents.length, req: { method: 'POST', url: 'https://graph.facebook.com/v23.0/2897515730634456/events', body: body(c.edgeEvents) } });
}
return reqs.map(json => ({ json }));

/*@lib*/
const setStep = (steps, key, status, reason) => steps.map(s => s.key === key ? (reason ? { key, status, reason } : { key, status }) : s);
const crm = $('CRM data').first().json;
const prev = $('Save progress 1').first().json.prev;
const sent = $('Meta requests').all().map(i => i.json), got = $('Meta: send conversions').all().map(i => i.json);
let steps = crm.steps, metaFailed = [];
const clients = Object.values(crm.clients).map(c => {
  let meta = { sent: 0, accepted: 0, rejected: 0 };
  sent.forEach((s, i) => {
    if (s.client !== c.client || !s.count) return;
    const r = got[i] || {};
    meta.sent += s.count;
    if (s.kind === 'main' && r.statusCode !== 200) { metaFailed.push(`${c.name}: Meta answered ${r.statusCode ?? 'nothing'}`); meta = null; return; }
    if (!meta) return;
    const ok = r.statusCode === 200 ? Number(r.body?.events_received) || 0 : 0;
    if (s.kind === 'main') meta.accepted += ok;
    meta.rejected += s.count - ok;
  });
  const weekStart = new Date(crm.weekStart);
  const kpis = computeKpis(c.client, c.leads, c.spend, weekStart);
  const warnings = runChecks({ client: c.client, leads: c.leads, spend: c.spend, meta, weekStart });
  const previousKpis = prev?.clients?.find(p => p.client === c.client)?.kpis ?? null;
  return { client: c.client, name: c.name, kpis, previousKpis, warnings, skipped: c.skipped };
});
steps = setStep(steps, 'meta', metaFailed.length ? 'failed' : 'done', metaFailed.join('; ') || undefined);
steps = setStep(steps, 'checks', 'done');
steps = setStep(steps, 'ai', 'running');
const aiInput = buildAiInput(clients);
const aiBody = { messages: [{ role: 'system', content: "You write the weekly results summary that a marketing agency's account manager reads before sending reports to two clients. Use plain, friendly English. Never type a digit. Wherever a number goes, write a placeholder from that client's \"placeholders\" list in curly braces, exactly as named, for example {costPerLead}. Code replaces each placeholder with the value listed next to it, so you can see what the reader will see. Never calculate new numbers. Use only the placeholders of the client you are writing about. The overview covers both clients and has no numbers or placeholders. Placeholders ending in _change already say which way it went (for example \"up 5%\" or \"down 33%\"): write \"leads were {leads_change} on the previous report\", never \"leads rose {leads_change}\". Outside the curly braces, never write field names such as costPerLead or paidLeads; say \"cost per lead\" or \"paid leads\". The data covers last week (Monday to Sunday). Changes compare with the previous report, not with an earlier week: call it \"the previous report\", never \"the previous week\" or \"the week before\". Keep each summary to two or three sentences: say what matters most this week and why, using only the few numbers that support it. Do not list every number; the report shows them all in a table. Explain every warning in client-friendly words, and suggest at most three practical next steps per client. A warning's message contains numbers, so never copy it: explain it in your own words with {<code>_count} (for example {duplicates_count}), or write {<code>_message} on its own to show the check's wording. Every placeholder needs its own label within a few words of it, in the same sentence, like these examples. A placeholder without its label nearby, or right after another number's label, makes the answer invalid.\n{spend}: next to \"spend\" or \"spent\" or \"budget\", e.g. \"ad spend was {spend}\"\n{leads}: next to \"lead\" or \"enquiry\" or \"enquiries\", e.g. \"{leads} leads came in\"\n{paidLeads}: next to \"paid lead\" or \"from ads\" or \"from paid\", e.g. \"{paidLeads} paid leads\"\n{costPerLead}: next to \"per lead\" or \"per paid lead\" or \"each lead\" or \"each paid lead\", e.g. \"cost per paid lead was {costPerLead}\"\n{cancelled}: next to \"cancel\" or \"refund\", e.g. \"{cancelled} cancelled bookings\"\n{bookings}: next to \"booking\" or \"booked\" or \"consultation\" or \"appointment\", e.g. \"{bookings} booked consultations\"\n{costPerBooking}: next to \"per booking\" or \"each booking\" or \"per consultation\" or \"per appointment\", e.g. \"cost per booking was {costPerBooking}\"\n{bookingRate}: next to \"rate\" or \"of leads\" or \"of all leads\", e.g. \"a booking rate of {bookingRate}\"\n{orders}: next to \"order\" or \"purchase\", e.g. \"{orders} orders\"\n{revenue}: next to \"revenue\" or \"sales\" or \"income\", e.g. \"revenue was {revenue}\"\n{roas}: next to \"return on ad spend\" or \"roas\", e.g. \"return on ad spend was {roas}\"\n{costPerOrder}: next to \"per order\" or \"each order\", e.g. \"cost per order was {costPerOrder}\"\n{avgOrderValue}: next to \"average order\" or \"order value\", e.g. \"the average order was {avgOrderValue}\"\nA {name_change} placeholder needs the same label as {name}, e.g. \"leads were {leads_change} on the previous report\" or \"cost per lead was {costPerLead_change} on the previous report\".\n{meta_mismatch_count}: next to \"meta\" or \"facebook\", e.g. \"Meta is missing {meta_mismatch_count} bookings\"\n{missing_source_count}: next to \"source\" or \"which ad\" or \"where they came\" or \"where it came\", e.g. \"{missing_source_count} leads have no recorded source\"\n{duplicates_count}: next to \"twice\" or \"duplicate\" or \"same person\" or \"more than once\", e.g. \"{duplicates_count} leads appear twice\"\n{bad_totals_count}: next to \"total\", e.g. \"{bad_totals_count} total that does not add up\"\n{outlier_count}: next to \"order\" or \"large\" or \"unusual\", e.g. \"{outlier_count} unusually large order\"\n{meta_rejected_count}: next to \"meta\" or \"facebook\" or \"reject\" or \"refuse\" or \"refused\", e.g. \"Meta rejected {meta_rejected_count} events\"\nA {code_message} placeholder is the check's own sentence: put it on its own, e.g. \"{duplicates_message}\". Stay inside the length limits, counted after the placeholders are filled in: overview one sentence under 200 characters, headline under 90, summary under 600, each warning under 300, each next step under 200. Return JSON that matches the schema exactly. 'clinic' is the clinic, 'store' is the store." }, { role: 'user', content: JSON.stringify(aiInput) }],
  response_format: { type: 'json_schema', json_schema: { name: 'weekly_report', strict: true, schema: AI_SCHEMA } } };
return [{ json: { ...crm, clients, aiInput, aiBody, steps } }];

/*@lib*/
const ck = $('Checks').first().json;
return [{ json: { ok: !!pickAiAnswer($input.all().map(i => i.json), ck.aiInput, ck.problems.includes('ai_broken')).value } }];

/*@lib*/
const setStep = (steps, key, status, reason) => steps.map(s => s.key === key ? (reason ? { key, status, reason } : { key, status }) : s);
const ck = $('Checks').first().json;
// the first model's answer, then the second model's if it was asked
const replies = ['AI: write summary', 'AI: second try'].filter(n => $(n).isExecuted).flatMap(n => $(n).all().map(i => i.json));
const pick = pickAiAnswer(replies, ck.aiInput, ck.problems.includes('ai_broken'));
let steps = ck.steps, ai;
if (pick.value) { ai = { source: 'ai', value: pick.value }; steps = setStep(steps, 'ai', 'done'); }
else {
  ai = { source: 'template', value: templateSummary(ck.aiInput) };
  steps = pick.gotAnswer ? setStep(steps, 'ai', 'warning', `AI answer rejected (${pick.errors[0]}); template summary used`)
    : setStep(steps, 'ai', 'failed', `${pick.errors[0] || 'no AI answer'}; template summary used`);
}
const metaSkipped = ck.clients.reduce((a, c) => a + c.skipped, 0);
const report = buildReport({ runId: ck.runId, weekStart: ck.weekStart, clients: ck.clients, steps, ai, problems: ck.problems, metaSkipped });
return [{ json: { runId: ck.runId, status: report.partial ? 'partial' : 'done', report, steps } }];
